  `due_date`,
  `exchange_rate`,
  `functional_area_code`,
  `group_currency_code`,
  `internal_order_number`,
  `line_item_number`,
  `material_number`,
  `payment_terms_code`,
  `plant_code`,
  `posting_key`,
  `quantity`,
  `reference_document_number`,
  `reversal_indicator`,
  `reversed_document_number`,
  `special_gl_indicator`,
  `storage_location_code`,
  `tax_amount`,
  `tax_code`,
  `text_description`,
  `trading_partner_code`,
  `transaction_currency_code`,
